package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

class CommandLine_GetOptionValuesCharTest {

    /**
     * A small subclass that overrides getOptionValues(String) so we can verify
     * that getOptionValues(char) delegates to the String-based variant and
     * that the char is converted to a String with String.valueOf.
     */
    private static class TestCommandLine extends CommandLine {
        String captured;
        @Override
        public String[] getOptionValues(final String optionName) {
            this.captured = optionName;
            return new String[] { "one", "two" };
        }
        String getCaptured() { return captured; }
    }

    @Test
    void delegatesToStringVariant_returnsArray() {
        TestCommandLine cmd = new TestCommandLine();
        String[] values = cmd.getOptionValues('a');

        assertArrayEquals(new String[] { "one", "two" }, values, "Should return the array provided by the String-based override");
        assertEquals("a", cmd.getCaptured(), "The char should be converted to its String representation and passed through");
    }

    @Test
    void delegatesToStringVariant_nullPropagation() {
        // override to return null to ensure null is propagated
        CommandLine cmd = new CommandLine() {
            String captured;
            @Override
            public String[] getOptionValues(final String optionName) {
                this.captured = optionName;
                return null;
            }
            String getCaptured() { return captured; }
        };

        String[] values = cmd.getOptionValues('z');
        assertNull(values, "When the String-based variant returns null, the char-based should also return null");
    }

    @Test
    void privateConstructor_and_internalState_viaReflection() throws Exception {
        // Prepare lists to pass into the private constructor
        List<String> args = new LinkedList<>();
        List<Object> options = new ArrayList<>();

        // Obtain the private constructor (List, List, Consumer) and instantiate
        Constructor<CommandLine> ctor =
                CommandLine.class.getDeclaredConstructor(List.class, List.class, Consumer.class);
        ctor.setAccessible(true);
        CommandLine cmd = ctor.newInstance(args, options, (Consumer<?>) null);

        // Verify internal fields were set to the provided lists via reflection
        Field argsField = CommandLine.class.getDeclaredField("args");
        argsField.setAccessible(true);
        Object argsFieldValue = argsField.get(cmd);
        assertSame(args, argsFieldValue, "args field should reference the provided args list");

        Field optionsField = CommandLine.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        Object optionsFieldValue = optionsField.get(cmd);
        assertSame(options, optionsFieldValue, "options field should reference the provided options list");

        // With no options configured, calling getOptionValues(char) should return null (propagated)
        String[] values = cmd.getOptionValues('x');
        assertNull(values, "With an empty options list, getOptionValues(char) should return null");
    }
}

